import java.util.ArrayList;
import java.util.List;

public class BackoffRetrierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static FlakyCall failsUntil(int firstGoodAttempt, int[] calls) {
        return attemptNumber -> {
            calls[0]++;
            if (attemptNumber < firstGoodAttempt) {
                throw new Exception("boom on " + attemptNumber);
            }
            return "ok on " + attemptNumber;
        };
    }

    static Object run(FlakyCall call, int maxAttempts, long baseMillis, DelayLog delays) {
        try {
            return BackoffRetrier.callWithBackoff(call, maxAttempts, baseMillis, delays);
        } catch (Throwable crash) {
            return crash.getClass().getSimpleName() + ": " + crash.getMessage();
        }
    }

    static Object causeMessage(FlakyCall call, int maxAttempts, long baseMillis, DelayLog delays) {
        try {
            BackoffRetrier.callWithBackoff(call, maxAttempts, baseMillis, delays);
            return "<no exception>";
        } catch (Throwable crash) {
            Throwable cause = crash.getCause();
            return cause == null ? "<no cause>" : cause.getMessage();
        }
    }

    public static void main(String[] args) {
        int[] calls = new int[1];
        List<Long> waits = new ArrayList<>();
        DelayLog log = millis -> waits.add(millis);

        check("returns the first successful result", "ok on 1",
                run(failsUntil(1, calls), 3, 100L, log));

        calls[0] = 0;
        waits.clear();
        check("returns the result of a later attempt", "ok on 3",
                run(failsUntil(3, calls), 4, 100L, log));
        check("the backoff doubles between failures", "[100, 200]", waits.toString());

        calls[0] = 0;
        waits.clear();
        check("gives up with a summary exception",
                "IllegalStateException: gave up after 3 attempts",
                run(failsUntil(99, calls), 3, 100L, log));
        check("no wait is reported after the final attempt", "[100, 200]", waits.toString());

        calls[0] = 0;
        waits.clear();
        check("the last failure survives as the cause", "boom on 3",
                causeMessage(failsUntil(99, calls), 3, 100L, log));

        calls[0] = 0;
        waits.clear();
        check("rejects maxAttempts below 1",
                "IllegalArgumentException: maxAttempts must be at least 1",
                run(failsUntil(1, calls), 0, 100L, log));
        check("the task is never called when maxAttempts is 0", 0, calls[0]);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

