/**
 * TASK: Retry a flaky call with exponential backoff -- without ever sleeping.
 *
 * callWithBackoff(call, maxAttempts, baseMillis, delays):
 *   - throws IllegalArgumentException("maxAttempts must be at least 1") and
 *     calls nothing when maxAttempts is below 1,
 *   - otherwise runs call.attempt(n) for n = 1, 2, ... up to maxAttempts and
 *     returns the first result that comes back without an exception,
 *   - after a FAILED attempt n, and only while another attempt remains, reports
 *     the wait it would have taken: delays.waited(baseMillis * 2^(n-1)).
 *     With baseMillis 100 that is 100, then 200, then 400.
 *     Nothing is reported after the last attempt -- nobody waits to give up.
 *   - if every attempt fails, throws
 *     IllegalStateException("gave up after " + maxAttempts + " attempts")
 *     with the LAST failure as its cause.
 *
 * Do not call Thread.sleep: the DelayLog stands in for waiting so the method
 * stays instant and testable.
 */
interface FlakyCall {
    /* Provided -- do not edit. */
    String attempt(int attemptNumber) throws Exception;
}

interface DelayLog {
    /* Provided -- do not edit. */
    void waited(long millis);
}

public class BackoffRetrier {

    public static String callWithBackoff(FlakyCall call, int maxAttempts, long baseMillis, DelayLog delays) {
        if (maxAttempts < 1) {
            throw new IllegalArgumentException("maxAttempts must be at least 1");
        }
        Exception lastFailure = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return call.attempt(attempt);
            } catch (Exception failure) {
                lastFailure = failure;
                if (attempt < maxAttempts) {
                    delays.waited(baseMillis * (1L << (attempt - 1)));
                }
            }
        }
        throw new IllegalStateException("gave up after " + maxAttempts + " attempts", lastFailure);
    }
}
